#!/usr/bin/env node
// Verifies that every derived per-source chunk/index/manifest artifact
// (public/data, web-vue/public/data, docs/data) exactly matches the
// canonicalJobId set computed live from public/jobs.json -- the one
// authoritative snapshot (issue #164).
//
// Root cause of the drift this guards against: public/jobs.json /
// docs/jobs.json get edited directly by one-off data-migration scripts (see
// scripts/fix-*.js) and by several agent/cleanup passes, but the derived
// jobs-index.json / jobs-manifest.json / chunks/*.json files are only ever
// regenerated by explicitly running scripts/sync-web-data-files.js or
// scripts/rebuild-data-chunks-all.js afterward -- both of which already do a
// full rm+rebuild from public/jobs.json (there is no incremental-merge bug in
// either), so the actual defect is purely a missing-step problem: a
// migration that forgets to run the rebuild (or that runs a rebuild before,
// not after, a later cleanup pass) leaves the deployed site serving
// stale/extra records with no other signal catching it -- generatedAt/
// scrapedAt timestamps can look current on both sides even while the id sets
// disagree by hundreds of records. This script closes that gap by comparing
// the complete id sets (not just counts, which can coincidentally match even
// when the actual members differ) and failing loudly.
//
// Usage:
//   node scripts/verify-data-sync.js
//   node scripts/verify-data-sync.js --dirs=public/data,docs/data
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { attachCanonicalIds } from "./lib/canonical-id.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DEFAULT_DIRS = ["public/data", "web-vue/public/data", "docs/data"];

export function computeSourceCanonicalIds(jobsPayload) {
  const jobs = attachCanonicalIds(Array.isArray(jobsPayload?.jobs) ? jobsPayload.jobs : []);
  return new Set(jobs.map((job) => job.canonicalJobId));
}

export function computeIndexCanonicalIds(indexPayload) {
  const jobs = Array.isArray(indexPayload?.jobs) ? indexPayload.jobs : [];
  return new Set(jobs.map((job) => job?.canonicalJobId).filter(Boolean));
}

export function sumChunkCanonicalIds(chunkPayloads) {
  const ids = new Set();
  for (const payload of chunkPayloads) {
    for (const job of Array.isArray(payload?.jobs) ? payload.jobs : []) {
      if (job?.canonicalJobId) ids.add(job.canonicalJobId);
    }
  }
  return ids;
}

// Compares a derived artifact's id set against the source-of-truth id set.
// `stale` = present in the derived artifact but not in the source (the #164
// symptom -- a record public/jobs.json no longer has). `missing` = present in
// the source but absent from the derived artifact (the opposite drift, not
// seen in #164 but just as real a sync failure).
export function diffIdSets(sourceIds, derivedIds) {
  const stale = [...derivedIds].filter((id) => !sourceIds.has(id));
  const missing = [...sourceIds].filter((id) => !derivedIds.has(id));
  return { stale, missing, inSync: stale.length === 0 && missing.length === 0 };
}

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, "utf8"));
}

function readChunkPayloads(chunksDir) {
  if (!fs.existsSync(chunksDir)) return [];
  return fs
    .readdirSync(chunksDir)
    .filter((file) => file.endsWith(".json"))
    .map((file) => readJson(path.join(chunksDir, file)));
}

export function verifyDataSync({ root = ROOT, dirs = DEFAULT_DIRS } = {}) {
  const jobsPayload = readJson(path.join(root, "public/jobs.json"));
  const sourceIds = computeSourceCanonicalIds(jobsPayload);

  const results = [];
  for (const dir of dirs) {
    const absDir = path.join(root, dir);
    const indexPath = path.join(absDir, "jobs-index.json");
    if (!fs.existsSync(indexPath)) {
      results.push({ dir, skipped: true });
      continue;
    }
    const indexIds = computeIndexCanonicalIds(readJson(indexPath));
    const indexDiff = diffIdSets(sourceIds, indexIds);
    const chunkPayloads = readChunkPayloads(path.join(absDir, "chunks"));
    const chunkIds = sumChunkCanonicalIds(chunkPayloads);
    const chunkDiff = diffIdSets(sourceIds, chunkIds);
    results.push({
      dir,
      sourceCount: sourceIds.size,
      indexCount: indexIds.size,
      chunkCount: chunkIds.size,
      indexDiff,
      chunkDiff,
      inSync: indexDiff.inSync && chunkDiff.inSync,
    });
  }
  return { sourceCount: sourceIds.size, results, allInSync: results.every((r) => r.skipped || r.inSync) };
}

function main() {
  const dirsArg = process.argv.find((arg) => arg.startsWith("--dirs="));
  const dirs = dirsArg ? dirsArg.slice("--dirs=".length).split(",").filter(Boolean) : DEFAULT_DIRS;
  const { sourceCount, results, allInSync } = verifyDataSync({ dirs });

  console.log(`public/jobs.json: ${sourceCount} canonical job ids (source of truth)\n`);
  for (const r of results) {
    if (r.skipped) {
      console.log(`${r.dir}: SKIPPED (no jobs-index.json found)`);
      continue;
    }
    console.log(
      `${r.dir}: jobs-index.json ${r.indexCount} ids, chunks ${r.chunkCount} ids -- ${r.inSync ? "IN SYNC" : "MISMATCH"}`
    );
    if (!r.indexDiff.inSync) {
      if (r.indexDiff.stale.length) console.error(`  jobs-index.json has ${r.indexDiff.stale.length} stale id(s) not in public/jobs.json, e.g. ${r.indexDiff.stale.slice(0, 5).join(", ")}`);
      if (r.indexDiff.missing.length) console.error(`  jobs-index.json is missing ${r.indexDiff.missing.length} id(s) from public/jobs.json, e.g. ${r.indexDiff.missing.slice(0, 5).join(", ")}`);
    }
    if (!r.chunkDiff.inSync) {
      if (r.chunkDiff.stale.length) console.error(`  chunks/ have ${r.chunkDiff.stale.length} stale id(s) not in public/jobs.json, e.g. ${r.chunkDiff.stale.slice(0, 5).join(", ")}`);
      if (r.chunkDiff.missing.length) console.error(`  chunks/ are missing ${r.chunkDiff.missing.length} id(s) from public/jobs.json, e.g. ${r.chunkDiff.missing.slice(0, 5).join(", ")}`);
    }
  }

  if (!allInSync) {
    console.error("\nData sync verification FAILED. Run `node scripts/rebuild-data-chunks-all.js` and commit the result.");
    process.exit(1);
  }
  console.log("\nAll derived data directories match public/jobs.json exactly.");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}
